	public void SetData(Card card, bool isEnv = false, int envIndex = -1)
	{
		RectTransform animRect = m_View.Anim.transform as RectTransform;
		if (animRect != null)
		{
			animRect.anchoredPosition = Vector2.zero;
		}
		m_View.Anim.Play(ECardAnimName.Idle.ToString(), 0, 0);
		cachedCard = card;
		cachedCardType = (ECardType)System.Enum.Parse(typeof(ECardType), card.type);
		IsEnv = isEnv;
		EnvIndex = envIndex;
		m_IsMoving = false;

		m_View.CardName.text = card.cardName;
		m_View.CardImg.sprite = LoadSprite(card.cardImage);
		m_View.Description.text = card.description;
		m_View.IconType.sprite = LoadSprite(card.iconType);
		m_View.CardFrame.sprite = LoadSprite(card.cardFrame);

		SetTypeUI(card);
		SetStars(card.stars);
		CardEffect = GetCardEffect();
		IsEffecting = false;
	}

	private void SetTypeUI(Card card)
	{
		m_View.Attack.SetActive(false);
		m_View.Defence.SetActive(false);
		m_View.Moster.SetActive(false);

		switch (cachedCardType)
		{
			case ECardType.attack:
				m_View.Attack.SetActive(true);
				m_View.TxtAttack.text = card.attack.ToString();
				break;

			case ECardType.defence:
				m_View.Defence.SetActive(true);
				m_View.TxtDefence.text = card.defence.ToString();
				break;

			case ECardType.monster:
				m_View.Attack.SetActive(true);
				m_View.TxtAttack.text = card.attack.ToString();
				m_View.Moster.SetActive(true);
				m_View.TextHeart.text = card.currentHealth.ToString();
				break;

			case ECardType.skill:
				break;

			case ECardType.item:
				break;

			case ECardType.other:
				m_View.IconType.gameObject.SetActive(false);
				break;

			default:
				break;
		}
	}

	private void SetStars(int stars)
	{
		stars = Mathf.Clamp(stars, 0, 3);
		int childCount = m_View.StarLayout.transform.childCount;
		for (int i = 0; i < childCount; i++)
		{
			var starObj = m_View.StarLayout.transform.GetChild(i).gameObject;
			starObj.SetActive(i < stars);
		}
	}

	private Sprite LoadSprite(string path)
	{
		return Resources.Load<Sprite>(path);
	}

	public float PlayVFX(List<EVFXName> vfxNames, ECardAnimName animName = ECardAnimName.Idle, EVFXLife vfxLife = EVFXLife.CardLife)
	{
		vfxLife = EVFXLife.CardLife;
		RectTransform animRect = m_View.Anim.transform as RectTransform;
		if (animRect != null)
		{
			animRect.anchoredPosition = new Vector2(0, 0);

		}

		if (animName != ECardAnimName.Idle)
		{
			m_View.Anim.Play(animName.ToString(), 0, 0);
		}

		float maxDelayTime = 0f;
		if (animName != ECardAnimName.Idle)
		{
			float animDelayTime = DataSystem.Instance.GetAnimDelayTime(animName);
			if (animDelayTime > maxDelayTime)
			{
				maxDelayTime = animDelayTime;
			}
		}

		if (vfxNames != null && vfxNames.Count > 0)
		{
			for (int i = 0; i < vfxNames.Count; i++)
			{
				EVFXName vfxName = vfxNames[i];
				float delayTime = DataSystem.Instance.GetVFXDelayTime(vfxName);
				if (delayTime > maxDelayTime)
				{
					maxDelayTime = delayTime;
				}
			}

			for (int i = 0; i < vfxNames.Count; i++)
			{
				EVFXName vfxName = vfxNames[i];
				if (vfxLife == EVFXLife.SelfLife)
				{
					if (EnvIndex >= 0)
					{
						JoeyGameControl.Instance.PlayEnvVFX(vfxName, EnvIndex, maxDelayTime);
					}
					else
					{
						JoeyGameControl.Instance.PlayVFX(vfxName, CacheTrans, maxDelayTime);
					}
				}
				else if (vfxLife == EVFXLife.CardLife)
				{
					Transform vfxTransform = JoeyGameControl.Instance.GetVFX(vfxName, CacheTrans);
					EffectEntityList.Add(vfxTransform);

					DelayHideCardLifeVFX(vfxTransform, maxDelayTime).Forget();

				}
			}
		}
		return maxDelayTime;
	}


	public async UniTaskVoid DelayHideCardLifeVFX(Transform vfxTransform, float delayTime)
	{
		var cts = new CancellationTokenSource();
		CancelTokenList.Add(cts);
		await UniTask.WaitForSeconds(delayTime, cancellationToken: cts.Token);
		if (vfxTransform != null && vfxTransform.gameObject != null)
		{
			JoeyGameControl.Instance.ReturnVFXPool(vfxTransform, EnvIndex);
			EffectEntityList.Remove(vfxTransform);
		}
		CancelTokenList.Remove(cts);
		cts.Dispose();
	}



	public void StopAllEffects()
	{
		for (int i = 0; i < CancelTokenList.Count; i++)
		{
			var cts = CancelTokenList[i];
			if (cts != null && !cts.IsCancellationRequested)
			{
				cts.Cancel();
				cts.Dispose();
			}
		}
		CancelTokenList.Clear();
	}

	protected override void OnReturn()
	{
		StopAllEffects();

		for (int i = 0; i < EffectEntityList.Count; i++)
		{
			var go = EffectEntityList[i];
			if (go != null)
			{
				JoeyGameControl.Instance.ReturnVFXPool(go, EnvIndex);
			}
		}
		m_View.Anim.Play(ECardAnimName.Idle.ToString(), 0, 0);
		RectTransform animRect = m_View.Anim.transform as RectTransform;
		if (animRect != null)
		{
			animRect.anchoredPosition = Vector2.zero;
		}
		m_IsMoving = false;
		for (int i = 0; i < m_BuffValueArray.Length; i++)
		{
			m_BuffValueArray[i] = 0;
		}
		gameObject.SetActive(false);
		EffectEntityList.Clear();
		base.OnReturn();
	}

